// 新实现只验原真实轮次的M14伤害/人数/RNG隔离；不把有限夹具当XP历史或World。
#include "resident/domains/military/military_combat_conditions.hpp"
#include "resident/domains/military/military_commanded_damage.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code+":"+r.error.original.path);return std::move(r.value);}void good(Status s){if(!s.ok)throw std::runtime_error(s.error.original.code);}
MilitaryBattleCatalog catalog(){MilitaryBattleCatalog c;c.rout_retreat_enabled=true;c.combat_condition_rule=MilitaryCombatConditionRule{};BattlefieldDefinition board;board.id="field";board.objective_id="goal";board.rout_retreat=MilitaryRoutRetreatRule{};board.damage_model.kind="legacy_base_factors_v1";board.damage_model.present=true;board.damage_model.empty=false;for(Integer q=0;q<3;++q){HexCell cell;cell.q=q;cell.terrain="plain";board.cells.push_back(cell);}board.spawns={{0,{0,0},{}},{1,{2,0},{}}};board.exits=board.spawns;c.battlefields={board};BattleObjectiveDefinition goal;goal.id="goal";goal.kind="repel";goal.max_rounds=10;c.objectives={goal};TroopDefinition t;t.id="foot";t.category="infantry";t.movement=1;t.attack=100;t.accuracy=100;t.movement_costs={{"plain",1},{"forest",1},{"hill",1},{"water",0},{"wall",0}};c.troop_types={t};return c;}
MilitaryBattleRecord frame(Integer fatigue){MilitaryBattleRecord b;b.id="battle:1";b.battlefield_id="field";b.objective_id="goal";b.rout_retreat_enabled=true;b.controller_actor_id="captain";b.command_scope="unit";b.command_unit_ids={"unit"};BattleUnit u;u.unit_id="unit";u.army_id="army:1";u.commander_actor_id="captain";u.troop_type_id="foot";u.morale=100;for(Integer i=0;i<100;++i)u.fit.push_back("u"+std::to_string(i));u.member_ids=u.fit;BattleUnit e=u;e.unit_id="enemy";e.army_id="army:2";e.commander_actor_id="other";e.side=1;e.position={1,0};e.heading=3;e.fit.clear();for(Integer i=0;i<100;++i)e.fit.push_back("e"+std::to_string(i));e.member_ids=e.fit;b.units={u,e};b.ai_plans={{"enemy",{"wait",e.position,e.heading,{},{},{}}}};MilitaryCombatConditionState state;state.units={{"enemy","camp",{},Integer(20),Integer(0),10000,{}},{"unit","camp","military:4",Integer(20),fatigue,take(military_combat_fatigue_efficiency(fatigue)),{}}};b.combat_conditions=std::move(state);return b;}
}
namespace {
MilitaryBattleRecord commanded(Integer fatigue){auto b=frame(fatigue);MilitaryCommandedDamageState state;for(const auto& id:{StableId("enemy"),StableId("unit")}){const BattleUnit* u=nullptr;for(const auto& row:b.units)if(row.unit_id==id)u=&row;MilitaryCommandedDamageUnit r;r.unit_id=id;r.commander_actor_id=u->commander_actor_id;r.troop_type_id=u->troop_type_id;r.skill_id="infantry";r.authored_actor_id=r.commander_actor_id;r.command_source={MilitaryUnitCommandSourceKind::authored,id};r.leadership=60;r.experience=300;r.level=2;r.training=20;state.units.push_back(r);}b.commanded_damage=std::move(state);return b;}
MilitaryOrder attack_order(const MilitaryBattleRecord& b){MilitaryOrder o;o.action="attack";o.destination=b.units[0].position;o.target_id="enemy";return o;}
}
int main(){try{
 auto cat=catalog();cat.commanded_damage_rule=MilitaryCommandedDamageRule{};
 for(const auto& row:{std::pair<Integer,Integer>{0,7},{40,6},{70,5},{90,4}}){auto b=commanded(row.first);good(validate_military_battle(b,cat,true));auto command=attack_order(b);auto q=take(preview_military_order(b,cat,"unit",command));check(q.hit_chance==100&&q.casualties_min==row.second&&q.casualties_max==row.second,"exact frozen qualification and fatigue quote");Integer draws=0;auto result=take(resolve_military_round(b,cat,"captain",{{"unit",command}},[&](StableId&,StableId&,Integer,Integer)->Outcome<Integer>{++draws;return {true,100,{}};}));const auto& target=result.units[1];check(draws==0,"ordinary new damage never draws legacy remainder RNG");check(target.wounded.size()==std::size_t(row.second*60/100)&&target.dead.size()==std::size_t(row.second-row.second*60/100),"sixty percent wounded and remaining dead");check(target.fit.size()+target.wounded.size()+target.dead.size()+target.captured.size()+target.deserted.size()==100,"original people conserved");check(target.morale==100-std::min<Integer>(20,2+row.second),"original target morale formula");}
 auto b=commanded(0);b.ai_plans[0].second.action="defend";auto after=take(resolve_military_round(b,cat,"captain",{{"unit",attack_order(b)}},{}));check(after.units[1].wounded.size()+after.units[1].dead.size()==5,"defend is original eighty percent factor");
 b=commanded(0);b.commanded_damage->units[1].experience=100;check(!validate_military_battle(b,cat).ok,"forged XP level rejected");b=commanded(0);b.commanded_damage->units[1].training=21;check(!validate_military_battle(b,cat).ok,"training must match original entry condition");b=commanded(0);b.commanded_damage->units[1].commander_actor_id="other";check(!validate_military_battle(b,cat).ok,"commander cannot be substituted");b=commanded(0);b.commanded_damage.reset();check(!validate_military_battle(b,cat).ok,"enabled entry missing qualification rejected");
 auto old=frame(0);auto legacy=cat;legacy.commanded_damage_rule.reset();Integer draws=0;auto prior=take(resolve_military_round(old,legacy,"captain",{{"unit",attack_order(old)}},[&](StableId&,StableId&,Integer,Integer)->Outcome<Integer>{++draws;return {true,100,{}};}));check(draws==1&&prior.units[1].fit.empty(),"old thirteen damage and original draw unchanged");
 std::cout<<"MILITARY_COMMANDED_DAMAGE_ROUND="<<checks<<" FAILURES=0 SCOPE=NEW_IMPLEMENTATION_ORIGINAL_ROUND_COMPONENT\n";return 0;
}catch(const std::exception& e){std::cerr<<"MILITARY_COMMANDED_DAMAGE_ROUND_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
